<script setup lang="ts">
import {ref,onMounted} from 'vue';
import Dropdown from '../../shell/Dropdown.vue';
import HelpHint from './HelpHint.vue';
import {quality,qualityOptions,setBackgroundQuality} from '../home/backgroundMedia';
const snapshot=ref<{requests:number;bytes:number;ttfb:number|null;domReady:number|null}>({requests:0,bytes:0,ttfb:null,domReady:null});
function refresh(){const nav=performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming|undefined;const resources=performance.getEntriesByType('resource') as PerformanceResourceTiming[];snapshot.value={requests:resources.length,bytes:resources.reduce((sum,r)=>sum+r.transferSize,0),ttfb:nav?Math.round(nav.responseStart-nav.requestStart):null,domReady:nav?.domContentLoadedEventEnd?Math.round(nav.domContentLoadedEventEnd):null};}
onMounted(refresh);
</script>
<template><section class="performance-card"><header><h2>本页性能 <HelpHint label="性能读数说明">当前浏览器读数，不代表生产基准或优化前后比较；跨域与缓存资源可能显示零字节。</HelpHint></h2><button class="st-button" @click="refresh">刷新性能读数</button></header><dl><dt>文档 TTFB</dt><dd>{{snapshot.ttfb===null?'不可读':snapshot.ttfb+' ms'}}</dd><dt>DOM ready</dt><dd>{{snapshot.domReady===null?'尚未记录':snapshot.domReady+' ms'}}</dd><dt>已记录资源请求</dt><dd>{{snapshot.requests}}</dd><dt>已记录传输字节</dt><dd>{{snapshot.bytes}}</dd></dl><div class="row"><span>背景画质<HelpHint label="背景画质保存说明">背景画质仅保存到当前设备。</HelpHint></span><Dropdown :model-value="quality" :options="qualityOptions" @update:model-value="setBackgroundQuality" /></div><RouterLink class="setting-doc-link" to="/help?section=guide&page=settings">性能读数、缓存与保存说明 →</RouterLink></section></template>
<style scoped>.performance-card{padding:20px;border:1px solid var(--control-border,var(--accent-dim));border-radius:14px;background:var(--bg-panel);margin-bottom:18px}header{display:flex;justify-content:space-between;align-items:center;gap:12px}h2{font-size:15px}p{font-size:12px;color:var(--text-lo);line-height:1.7;margin:12px 0}dl{display:grid;grid-template-columns:auto 1fr;gap:12px;font-size:13px}dt{color:var(--text-lo)}dd{margin:0}.row{display:flex;align-items:center;gap:12px;margin-top:18px;font-size:13px}button:not(.st-button){padding:7px 12px;background:var(--bg-raised);border:1px solid var(--control-border,var(--accent-dim));border-radius:7px;color:var(--text-hi);white-space:nowrap;cursor:pointer}</style>
